class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        matrix = [[0 for i in range(n)] for j in range(2)]
        for col,summ in enumerate(colsum):
            if summ == 0:
                continue
            if summ == 2:
                matrix[0][col] = matrix[1][col] = 1
                upper -= 1
                lower -= 1
            else:
                if upper > lower:
                    matrix[0][col] = 1
                    upper -= 1
                else:
                    matrix[1][col] = 1
                    lower -= 1
            if upper < 0 or lower < 0: break

        return matrix if upper == lower == 0 else []

class Solution(object):
    def groupThePeople(self, groupSizes):
        dict_group={}
        for i in range(len(groupSizes)):
            if groupSizes[i] not in dict_group:
                dict_group[groupSizes[i]]=[i]
            else:
                dict_group[groupSizes[i]].append(i)
        return_list=[]
        for i in dict_group:
            num_list=dict_group[i]
            for j in range(0,len(num_list),i):
                return_list.append(num_list[j:j+i])
        return return_list

